DECLARE @FDM DATE;
DECLARE @FDNM DATE;

SELECT @FDM = FIRSTDAYOFMONTH FROM EDS.DATE_DIM WHERE FULLDATE = @DATEPROCESSED
SELECT @FDNM = FIRSTDAYOFNEXTMONTH FROM EDS.DATE_DIM WHERE FULLDATE = @DATEPROCESSED

IF OBJECT_ID('D360.STG_EDS_DF_CURRENT_MONTH', 'U') IS NOT NULL
    DROP TABLE D360.STG_EDS_DF_CURRENT_MONTH;

DECLARE @SQL NVARCHAR(MAX) = '
CREATE TABLE [D360].[STG_EDS_DF_CURRENT_MONTH]

WITH (
    DISTRIBUTION = HASH(GAM_ACID),
    HEAP,
    PARTITION
	(
		[AS_OF_DATE] RANGE RIGHT FOR VALUES (''' + 
        CONVERT(VARCHAR(10), @FDM, 120) + ''',''' +
        CONVERT(VARCHAR(10), @FDNM, 120) + '''
        )
    )
)
AS
SELECT
    *
FROM EDS.DEPOSIT_FACT
WHERE AS_OF_DATE < ''' + CONVERT(VARCHAR(10), @FDNM, 120) + ''' AND AS_OF_DATE >= ''' + CONVERT(VARCHAR(10), @FDM, 120) + ''';

DELETE FROM [D360].[STG_EDS_DF_CURRENT_MONTH] WHERE AS_OF_DATE = ''' + CONVERT(VARCHAR(10), @DATEPROCESSED, 120) + ''';
';

EXEC (@SQL);
